    def __neg__(self):
        return Fraction(-self.p, self.q)

    def __abs__(self):
        if self.p < 0:
            return -self
        else:
            return self

    def __int__(self):
        return self.p // self.q

    def __float__(self):
        return self.p / self.q

    def __round__(self, digits = 0):
        return round(float(self), digits)

