                self.p = int(p)
                self.q = 1
            else:
                self.p = int(p[:i])
                self.q = int(p[i + 1:])
        if reduced:
            self.reduce()

    def reduce(self):
        g = gcd(self.p, self.q)
        self.p //= g
        self.q //= g

    def __str__(self):
        if self.q == 1:
            return(str(self.p))
        else:
            return(str(self.p) + '/' + str(self.q))

    def __lt__(self, other):
        self.reduce()
        if type(other) == float or type(other) == int:
            return self.p < other * self.q
        else:
            other.reduce()
            return self.p * other.q < self.q * other.p

    def __le__(self, other):
        self.reduce()
        if type(other) == float or type(other) == int:
            return self.p <= other * self.q
        else:
            other.reduce()
            return self.p * other.q <= self.q * other.p

    def __gt__(self, other):
        self.reduce()
        if type(other) == float or type(other) == int:
            return self.p > other * self.q
        else:
            other.reduce()
            return self.p * other.q > self.q * other.p

    def __ge__(self, other):
