    self.p[x] += self.p[y]
    self.p[y] = x
    return x
  def same(self, a, b):
    return self.leader(a)==self.leader(b)
  def size(self, a):
    return -self.p[self.leader(a)]
  def count(self):
    return sum(i<0 for i in self.p)
  def groups(self):
    leader_buf = [0]*self.n
    group_size = [0]*self.n
    res = [set() for _ in range(self.n)]
