        self._size = 1
        self._factorial_inv = [1]
        self._size_inv = 1
        self._mint = partial(Mint, mod=mod)

    def __call__(self, n):
        return self.fact(n)

    def fact(self, n):
        n = self._mint(n).x
        """ n! (mod m) """
        if n >= self.mod:
            return 0
        self._make(n)
        return self._mint(self._factorial[n])

    def _make(self, n):
        """ Calc from self._size to n!^-1 : O(n) """
        if n >= self.mod:
            n = self.mod
        if self._size < n+1:
            for i in range(self._size, n+1):
                self._factorial.append(self._factorial[i-1]*i % self.mod)
            self._size = n+1

    def fact_inv(self, n):
