        result = []
        if type(other) == Poly:
            for i in range(max(len(self.list), len(other.list))):
                if i < len(self.list):
                    if i < len(other.list):
                        result.append(self.list[i] + other.list[i])
                    else:
                        result.append(self.list[i])
                else:
                    if i < len(other.list):
                        result.append(other.list[i])
                    else:
                        result.append(0)
            return Poly(result)
        else:
            lolka = [self.list[0] + other] + self.list[1:]
            return Poly(lolka)

