            result = result * other + self.list[i]
        return result

    def __mul__(self, other):
        result, p = [], Poly(other)
        for i in range(len(self.list)):
            for j in range(len(p.list)):
                if len(result) > i + j:
                    result[i + j] += self.list[i] * p.list[j]
                else:
                    result += [0] * (i + j - len(result)) + [self.list[i] * p.list[j]]
